mapper.select:
select count(1) > 0 from platform_tenant_namespace
where tenant_id = #{tenantId}
  and cluster_id = #{clusterId}
  and namespace = #{namespace}

select ut.user_id, ut.tenant_id, t.name tenant_name, t.cluster_id, t.service_account from platform_user_tenant ut
    inner join platform_tenant t on ut.tenant_id = t.id and ut.tenant_id = #{tenantId}
    inner join platform_user u on ut.user_id = u.id and u.username = #{username}
